namespace Fanex.Age.UI.TotalBets
{

    public partial class LiveCasino_Page : TotalBets_Page
    {

        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable LiveCasinoList = View as DataTable;

            LiveCasino_Template tpl = new LiveCasino_Template();
            tpl.Contents.LeagueContents.Clear();

            if (LiveCasinoList.Rows.Count > 0)
            {
                tpl.Contents.NotFound.Hide();

                // Render league content
                int currentLeagueId = 0;
                int matchIndex = 0;
                LiveCasino_Contents_LeagueContents_Block leagueBlock = new LiveCasino_Contents_LeagueContents_Block();
                LiveCasino_Contents_LeagueContents_MatchContents_Block matchBlock = new LiveCasino_Contents_LeagueContents_MatchContents_Block();

                for (int i = 0; i < LiveCasinoList.Rows.Count; i++)
                {
                    DataRow dr = LiveCasinoList.Rows[i];

                    int leagueId = Convert.ToInt32(dr["leagueid"]);

                    if (i == 0 || currentLeagueId != leagueId)
                    {
                        // New league, ignore first row
                        if (i != 0) tpl.Contents.LeagueContents.Append(leagueBlock);

                        matchIndex = 1;
                        currentLeagueId = leagueId;

                        leagueBlock.MatchContents.Clear();
                        leagueBlock.LeagueName = CacheRef.GetLeagueName(leagueId);
                    }
                    else
                    {
                        matchIndex++;
                    }

                    RenderMatchRow(matchBlock, dr, matchIndex, i + 1);

                    leagueBlock.MatchContents.Append(matchBlock);
                }

                if (leagueBlock != null) tpl.Contents.LeagueContents.Append(leagueBlock);
            }


            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            if (!Sunplus.Agent.Model.Entities.Permission.UserPermission.IsShowLiveCasino) Response.Redirect("../AccessDenied.aspx");

            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetLiveCasino();
        }
        #endregion

        #region Utility
        /// <summary>
        /// Render match row
        /// Only show link to bet list if odd and even is not null
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        /// <param name="matchIndex"></param>
        /// <param name="rowIndex"></param>
        private void RenderMatchRow(LiveCasino_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr, int matchIndex, int rowIndex)
        {
            // Render match content
            matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;
            matchBlock.ColorClass = (matchIndex % 2) == 0 ? Fanex.Age.UI.Common.RowBgEven : Fanex.Age.UI.Common.RowBgOdd;
            
            matchBlock.vNo = rowIndex.ToString();
            matchBlock.vEvent = CacheRef.GetBettype(dr["bettype"]) + " " + dr["showtime"].ToString();
            matchBlock.MatchId = dr["matchid"].ToString();

            #region get value infomation
            decimal vBanker = (decimal)dr["banker"];
            decimal vPlayer = (decimal)dr["player"];
            decimal vOthers = (decimal)dr["others"];
            decimal vTotal = vBanker + vPlayer + vOthers;
            #endregion

            //#region get betcount infomation
            //int betcountWarrior2ndBall = (int)dr["betcount_vBanker"];
            //int betcountWarrior3rdBall = (int)dr["betcount_vPlayer"];  
            //int betCountOEFT = (int)dr["betcount_OEfullTime"];
            //#endregion

            #region Render template
            matchBlock.vBanker = vBanker != 0 ? NegativeNumberRoundColor(vBanker) : "";
            matchBlock.vPlayer = vPlayer != 0 ? NegativeNumberRoundColor(vPlayer) : "";
            matchBlock.vOthers = vOthers != 0 ? NegativeNumberRoundColor(vOthers) : "";
            matchBlock.vTotal = vTotal != 0 ? NegativeNumberRoundColor(vTotal) : "";
            #endregion
        }

        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private static string NegativeNumberRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);

            return (num < 0) ? "<font color='#eb6003'>" + Formater.DecFormat(num, 0) + "</font>" : Formater.DecFormat(num, 0);
        }

        #endregion
    }

}
